{"fingerprint":"b14d9954f0e8ecfc9b75475dc85e64ee1adc207cbac9acd6d5d09e974aa478eb","path":"src/review_gauntlet/run_tui.py","rule_id":"data-validation","content":"_progress_bar() trusts its completed argument after calculate_progress_metrics() derives it from arbitrary coverage counts. If completed exceeds total (for example because coverage contains a negative pending/stale count that is clamped to 0 for incomplete but total is reduced by other states, or because callers invoke _progress_bar directly), filled can become larger than _BAR_WIDTH. That makes the bar exceed the intended fixed width and masks inconsistent input instead of clamping the rendered value. Clamp filled into [0, _BAR_WIDTH] before rendering.","suggestion_code":"def _progress_bar(completed: int, total: int) -> str:
    if total <= 0:
        return "[" + "·" * _BAR_WIDTH + "]"
    filled = min(_BAR_WIDTH, max(0, round((completed / total) * _BAR_WIDTH)))
    return "[" + "█" * filled + "░" * (_BAR_WIDTH - filled) + "]"","existing_code":"def _progress_bar(completed: int, total: int) -> str:
    if total <= 0:
        return "[" + "·" * _BAR_WIDTH + "]"
    filled = round((completed / total) * _BAR_WIDTH)
    return "[" + "█" * filled + "░" * (_BAR_WIDTH - filled) + "]"","start_line":434,"end_line":438,"thinking":"Data validation issue: rendering should not trust derived numeric inputs to be within display bounds.","imprecise":false}

