{"fingerprint":"8724e784a753b35ca5d7f0dd37174a8a27d40ec2c719576807592f81af3cc670","path":"src/review_gauntlet/run_tui.py","rule_id":"data-validation","content":"Coverage and finding counts silently accept boolean values because bool is a subclass of int. If malformed status data contains true/false for a count, the dashboard will report it as 1/0 instead of treating it as invalid or absent, which can make progress and findings totals misleading.","suggestion_code":"def _count_value(value: object) -> int:
    if isinstance(value, bool):
        return 0
    if isinstance(value, int):
        return max(0, value)","existing_code":"def _count_value(value: object) -> int:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return max(0, value)","start_line":454,"end_line":458,"thinking":"Dashboard metrics are derived from external session/status JSON dictionaries, so count parsing should not coerce booleans into numeric counts.","imprecise":false}

